// ─── ReviewScorecardTab.tsx ───────────────────────────────────────────────────
// Main entry tab for Review Scorecard.
// ► useRoleContext for current user
// ► Job-level table fetched from real SP API (GetRecruitmentDetails)
// ► Routes to CandidateList and HodViewScorecardDetail via location.state

import * as React from "react";
import { useLocation, useNavigate } from "react-router-dom";
import { useRoleContext } from "../../../../utilities/hooks/RoleContext";
import ReviewScorecardCandidateList from "../../components/ReviewScorecardCandidateList";
import HodViewScorecardDetail from "../../components/HodViewScorecardDetail";
import styles from "./Reviewscorecardtab.module.scss";
import { SCORECARD_ROUTES, TabName, StatusId as ScStatusId } from "../../config/ScorecardConfig";
import SPServices from "../../../../Services/SPService/SPServices";
import { ListNames, StatusId } from "../../../../utilities/Config";

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────
interface ReviewScorecardTabProps {
  employeeList?: any[];
  CurrentRoleID?: number[];
  CurrentUserEmailId?: string;
  userDetails?: any[];
  webURL?: string;
  navigation?: (path: string, options?: any) => void;
  stateValue?: any;
}

interface JobRow {
  ID: number;
  JobCodeId: number;
  JobCode: string;
  JobTitleEnglish: string;
  BusinessUnitCode: string;
  PositionRequest: string;
  Nationality: string;
  Status: string;
  StatusId: number;
  Department: string;
  NoOfPosition: number;
  tab: string;
  TabName: string;
}

const PAGE_SIZE_OPTIONS = [5, 10, 15] as const;

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────
const ReviewScorecardTab: React.FC<ReviewScorecardTabProps> = (props) => {
  const navigate = useNavigate();
  const location = useLocation();
  const { ADGroupData } = useRoleContext();

  const stateValue = (location.state as any) ?? props.stateValue ?? {};
  const nav = props.navigation ?? navigate;

  const CurrentRoleID: number[] = props.CurrentRoleID ?? ADGroupData?.roleIDs ?? [];
  const CurrentUserEmailId: string = props.CurrentUserEmailId ?? ADGroupData?.EmailId?.[0] ?? "";
  const employeeList: any[] = props.employeeList ?? [];
  const webURL: string = props.webURL ?? (localStorage.getItem("CareerPortalLink") ?? "");

  const userDetails: any[] = React.useMemo(() => {
    if (props.userDetails && props.userDetails.length > 0) return props.userDetails;
    if (!CurrentUserEmailId) return [{}];
    const matched = employeeList.filter(
      (e: any) => String(e?.Email ?? "").toLowerCase() === CurrentUserEmailId.toLowerCase(),
    );
    return matched.length > 0 ? matched : [{}];
  }, [CurrentUserEmailId, employeeList, props.userDetails]);

  // ── Route to sub-pages if location state has a specific candidate / job ──
  if (stateValue?.ID && stateValue?.StatusId !== undefined && stateValue?.RecruitmentID) {
    return (
      <HodViewScorecardDetail
        stateValue={stateValue}
        EmployeeList={employeeList}
        CurrentRoleID={CurrentRoleID}
        CurrentUserEmailId={CurrentUserEmailId}
        userDetails={userDetails}
        webURL={webURL}
        navigation={nav}
      />
    );
  }

  if (stateValue?.ID && stateValue?.JobCode) {
    return (
      <ReviewScorecardCandidateList
        stateValue={stateValue}
        EmployeeList={employeeList}
        CurrentRoleID={CurrentRoleID}
        navigation={nav}
      />
    );
  }

  // ── Job list table ─────────────────────────────────────────────────────────
  return <ReviewScorecardJobTable navigation={nav} tabName={stateValue?.TabName ?? TabName.ReviewScorecard} />;
};

// ─────────────────────────────────────────────────────────────────────────────
// Job list table sub-component
// ─────────────────────────────────────────────────────────────────────────────
interface ReviewScorecardJobTableProps {
  navigation: (path: string, options?: any) => void;
  tabName: string;
}

const ReviewScorecardJobTable: React.FC<ReviewScorecardJobTableProps> = ({ navigation, tabName }) => {
  const [rows, setRows] = React.useState<JobRow[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [rowsPerPage, setRowsPerPage] = React.useState(5);
  const [currentPage, setCurrentPage] = React.useState(1);
  const [sortKey, setSortKey] = React.useState<keyof JobRow>("JobCode");
  const [sortDirection, setSortDirection] = React.useState<"asc" | "desc">("asc");

  // Fetch jobs with HOD Review Scorecard statuses
  React.useEffect(() => {
    const load = async () => {
      setIsLoading(true);
      try {
        const res: any[] = await SPServices.SPReadItems({
          Listname: ListNames.HRMSRecruitmentDptDetails,
          Select:
            "*,Department/DepartmentName,Status/StatusDescription,JobCode/JobCode,BusinessUnitCode/BusineesUnitCode",
          Expand: "Department,Status,JobCode,BusinessUnitCode",
          Filter: [
            {
              FilterKey: "StatusId",
              Operator: "in",
              FilterValue: [
                StatusId.PendingwithHODtoselectthecandidate,
                StatusId.PendingwithHODtoAssignPositionID,
                StatusId.PendingwithHODtoselectthecandidateLevel2,
              ],
            },
          ],
          Topcount: 5000,
        });

        const mapped: JobRow[] = res.map((item: any) => ({
          ID: item.ID,
          JobCodeId: item.JobCodeId || item.JobCode?.ID || 0,
          JobCode: item.JobCode?.JobCode || "",
          JobTitleEnglish: item.JobTitleEnglish || "",
          BusinessUnitCode: item.BusinessUnitCode?.BusineesUnitCode || "",
          PositionRequest: item.AreaofWork || item.Type || "",
          Nationality: item.Nationality || "",
          Status: item.Status?.StatusDescription || "",
          StatusId: item.StatusId || 0,
          Department: item.Department?.DepartmentName || "",
          NoOfPosition: Number(item.NumberOfPersonNeeded) || 1,
          tab: "tab1",
          TabName: tabName,
        }));

        setRows(mapped);
      } catch (err) {
        console.error("ReviewScorecardJobTable load error:", err);
        setRows([]);
      } finally {
        setIsLoading(false);
      }
    };
    void load();
  }, [tabName]);

  // Sorting
  const sortedRows = React.useMemo(() => {
    return [...rows].sort((a, b) => {
      const av = String(a[sortKey] ?? "").toLowerCase();
      const bv = String(b[sortKey] ?? "").toLowerCase();
      const cmp = av.localeCompare(bv, undefined, { numeric: true, sensitivity: "base" });
      return sortDirection === "asc" ? cmp : -cmp;
    });
  }, [rows, sortKey, sortDirection]);

  const totalPages = Math.max(1, Math.ceil(sortedRows.length / rowsPerPage));
  const safePage = Math.min(currentPage, totalPages);
  const pageStart = (safePage - 1) * rowsPerPage;
  const pageRows = sortedRows.slice(pageStart, pageStart + rowsPerPage);

  React.useEffect(() => { setCurrentPage(1); }, [rowsPerPage, sortKey, sortDirection]);

  const handleSort = (key: keyof JobRow) => {
    if (sortKey === key) {
      setSortDirection((p) => (p === "asc" ? "desc" : "asc"));
    } else {
      setSortKey(key);
      setSortDirection("asc");
    }
  };

  const renderSortIcon = (key: keyof JobRow) => {
    if (sortKey !== key) return " ↑↓";
    return sortDirection === "asc" ? " ↑" : " ↓";
  };

  const handleReview = (row: JobRow) => {
    navigation(SCORECARD_ROUTES.CandidateList, {
      state: {
        ID: row.ID,
        JobCode: row.JobCode,
        JobCodeID: row.JobCodeId,
        Department: row.Department,
        Status: row.Status,
        TabName: tabName,
        tab: row.tab,
        NoOfPosition: row.NoOfPosition,
      },
    });
  };

  if (isLoading) {
    return (
      <div className={styles.container}>
        <div className={styles.card}>
          <div style={{ padding: "2rem", textAlign: "center", color: "#64748b" }}>Loading...</div>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.container}>
      <section className={styles.card}>
        <div className={styles.cardHeader}>
          <h2>Review Scorecards</h2>
          <button type="button" className={styles.backButton} onClick={() => navigation("/Dashboard")}>
            ↺ BACK TO DASHBOARD
          </button>
        </div>

        <div className={styles.tableContainer}>
          <table className={styles.styledTable}>
            <thead>
              <tr>
                <th onClick={() => handleSort("JobCode")}>JOB CODE{renderSortIcon("JobCode")}</th>
                <th onClick={() => handleSort("JobTitleEnglish")}>JOB TITLE{renderSortIcon("JobTitleEnglish")}</th>
                <th onClick={() => handleSort("BusinessUnitCode")}>BUSINESS UNIT{renderSortIcon("BusinessUnitCode")}</th>
                <th onClick={() => handleSort("PositionRequest")}>POSITION REQUEST{renderSortIcon("PositionRequest")}</th>
                <th onClick={() => handleSort("Nationality")}>NATIONALITY{renderSortIcon("Nationality")}</th>
                <th>STATUS</th>
                <th className={styles.center}>ACTION</th>
              </tr>
            </thead>
            <tbody>
              {pageRows.map((row) => (
                <tr key={row.ID}>
                  <td className={styles.jobCode}>{row.JobCode}</td>
                  <td className={styles.jobTitle}>{row.JobTitleEnglish}</td>
                  <td className={styles.textMuted}>{row.BusinessUnitCode}</td>
                  <td className={styles.textMuted}>{row.PositionRequest}</td>
                  <td className={styles.textMuted}>{row.Nationality}</td>
                  <td>
                    <span className={styles.statusBadge}>
                      <span className={styles.dot} />
                      {row.Status}
                    </span>
                  </td>
                  <td className={styles.center}>
                    <button type="button" className={styles.actionButton} onClick={() => handleReview(row)}>
                      REVIEW
                    </button>
                  </td>
                </tr>
              ))}
              {pageRows.length === 0 && (
                <tr>
                  <td colSpan={7} className={styles.noData}>
                    No review scorecards available.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        <div className={styles.paginationBar}>
          <div className={styles.paginationInfo}>
            <span>
              Showing <strong>{pageRows.length === 0 ? 0 : pageStart + 1}</strong> to{" "}
              <strong>{Math.min(pageStart + rowsPerPage, sortedRows.length)}</strong> of{" "}
              <strong>{sortedRows.length}</strong> results
            </span>
            <label className={styles.showEntries}>
              SHOW
              <select value={rowsPerPage} onChange={(e) => setRowsPerPage(Number(e.target.value))}>
                {PAGE_SIZE_OPTIONS.map((o) => <option key={o} value={o}>{o}</option>)}
              </select>
              ENTRIES
            </label>
          </div>
          <div className={styles.paginationControls}>
            <button
              type="button"
              className={`${styles.pageBtn} ${safePage === 1 ? styles.disabled : ""}`}
              onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
              disabled={safePage === 1}
            >‹</button>
            {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
              <button
                key={n}
                type="button"
                className={`${styles.pageBtn} ${safePage === n ? styles.activePage : ""}`}
                onClick={() => setCurrentPage(n)}
              >{n}</button>
            ))}
            <button
              type="button"
              className={`${styles.pageBtn} ${safePage === totalPages ? styles.disabled : ""}`}
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
              disabled={safePage === totalPages}
            >›</button>
          </div>
        </div>
      </section>
    </div>
  );
};

export { default as ReviewScorecardCandidateList } from "../../components/ReviewScorecardCandidateList";
export { default as HodViewScorecardDetail } from "../../components/HodViewScorecardDetail";
export default ReviewScorecardTab;
